/**
 * Unit tests: ci/duplicationRatchet.js (gh-1251 rework).
 *
 * The quality.yml duplication gate is a RATCHET, not an absolute bar: the
 * 85 production JS files already over 1% duplicated lines are pinned in
 * duplication-baseline.json (pre-existing debt owned by the gh-1244…gh-1250
 * dedup tickets) and only a NEW over-threshold file or an INCREASED
 * percentage fails the gate. These tests pin that behavior end to end:
 *
 *   - parseViolations: multi-item report parsing, summary-line/noise
 *     filtering, empty input.
 *   - compareWithBaseline: clean pass on identical debt, fresh-file
 *     regression, percentage-increase regression, percentage-decrease
 *     improvement, cleared debt, empty baseline, zero violations.
 *   - main: CLI exit codes for ratchet-clean, fresh regression, and a
 *     crashed measurement (tool exit other than 0/2 must never pass).
 *
 * Uses: loadModule, assert, test(), suite()
 */

'use strict';

/* global loadModule, require, assert, test, suite */

var ratchet = loadModule('ci/duplicationRatchet.js', require);

// ── parseViolations ──────────────────────────────────────────────────────────

suite('duplicationRatchet — parseViolations', function() {

    test('parses a multi-file report into file/line/percent entries', function() {
        var report = [
            'ci/release_packs.mjs:164: 2.30% duplicated lines > 1%',
            'js/createRepoTasks.js:19: 16.85% duplicated lines > 1%',
            'js/mergeTrigger.js:43: 1.01% duplicated lines > 1%'
        ].join('\n');
        var v = ratchet.parseViolations(report);
        assert.deepEqual(v, [
            { file: 'ci/release_packs.mjs', line: 164, percent: 2.30 },
            { file: 'js/createRepoTasks.js', line: 19, percent: 16.85 },
            { file: 'js/mergeTrigger.js', line: 43, percent: 1.01 }
        ]);
    });

    test('ignores the summary line and unrelated noise', function() {
        var report = [
            'some header noise',
            'js/moveToDone.js:8: 12.50% duplicated lines > 1%',
            '85/191 files over 1% duplication',
            'trailing note without a violation shape'
        ].join('\n');
        var v = ratchet.parseViolations(report);
        assert.deepEqual(v, [{ file: 'js/moveToDone.js', line: 8, percent: 12.50 }]);
    });

    test('empty report parses to no violations', function() {
        assert.deepEqual(ratchet.parseViolations(''), []);
        assert.deepEqual(ratchet.parseViolations('85/191 files over 1% duplication'), []);
    });

});

// ── compareWithBaseline ──────────────────────────────────────────────────────

function baselineOf(map) {
    return { version: 1, threshold: 1, pinned: map };
}

var DEBT = baselineOf({
    'js/moveToDone.js': 12.50,
    'js/mergeTrigger.js': 1.01
});

suite('duplicationRatchet — compareWithBaseline', function() {

    test('identical debt is clean — pinned files do not fail the gate', function() {
        var result = ratchet.compareWithBaseline([
            { file: 'js/moveToDone.js', line: 8, percent: 12.50 },
            { file: 'js/mergeTrigger.js', line: 43, percent: 1.01 }
        ], DEBT);
        assert.strictEqual(result.clean, true);
        assert.deepEqual(result.fresh, []);
        assert.deepEqual(result.regressions, []);
        assert.strictEqual(result.pinnedCount, 2);
    });

    test('a NEW file over threshold is a fresh regression', function() {
        var result = ratchet.compareWithBaseline([
            { file: 'js/moveToDone.js', line: 8, percent: 12.50 },
            { file: 'js/brandNewDup.js', line: 3, percent: 4.20 }
        ], DEBT);
        assert.strictEqual(result.clean, false);
        assert.deepEqual(result.fresh, [{ file: 'js/brandNewDup.js', percent: 4.20 }]);
        assert.strictEqual(result.regressions.length, 0);
    });

    test('an INCREASED percentage on a pinned file is a regression', function() {
        var result = ratchet.compareWithBaseline([
            { file: 'js/mergeTrigger.js', line: 43, percent: 1.50 },
            { file: 'js/moveToDone.js', line: 8, percent: 12.50 }
        ], DEBT);
        assert.strictEqual(result.clean, false);
        assert.deepEqual(result.regressions, [
            { file: 'js/mergeTrigger.js', from: 1.01, to: 1.50 }
        ]);
    });

    test('a DECREASED percentage is clean and reported as improved', function() {
        var result = ratchet.compareWithBaseline([
            { file: 'js/mergeTrigger.js', line: 43, percent: 0.99 },
            { file: 'js/moveToDone.js', line: 8, percent: 12.50 }
        ], DEBT);
        assert.strictEqual(result.clean, true);
        assert.deepEqual(result.improved, [
            { file: 'js/mergeTrigger.js', from: 1.01, to: 0.99 }
        ]);
    });

    test('debt cleared below threshold is clean and reported as cleared', function() {
        var result = ratchet.compareWithBaseline([
            { file: 'js/moveToDone.js', line: 8, percent: 12.50 }
        ], DEBT);
        assert.strictEqual(result.clean, true);
        assert.deepEqual(result.cleared, ['js/mergeTrigger.js']);
    });

    test('empty baseline makes every violation fresh', function() {
        var result = ratchet.compareWithBaseline([
            { file: 'js/moveToDone.js', line: 8, percent: 12.50 }
        ], baselineOf({}));
        assert.strictEqual(result.clean, false);
        assert.deepEqual(result.fresh, [{ file: 'js/moveToDone.js', percent: 12.50 }]);
    });

    test('zero violations is clean even with a non-empty baseline', function() {
        var result = ratchet.compareWithBaseline([], DEBT);
        assert.strictEqual(result.clean, true);
        assert.deepEqual(result.cleared, ['js/mergeTrigger.js', 'js/moveToDone.js']);
    });

});

// ── main (CLI) ───────────────────────────────────────────────────────────────

suite('duplicationRatchet — main CLI', function() {

    var fs = require('fs');
    var os = require('os');
    var path = require('path');

    var tmpDir;
    var reportPath;
    var baselinePath;

    function writeTmp(name, content) {
        var p = path.join(tmpDir, name);
        fs.writeFileSync(p, content);
        return p;
    }

    // suite()/test() have no beforeEach in this harness — set up per test.
    function setup() {
        tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'dup-ratchet-'));
        baselinePath = writeTmp('baseline.json', JSON.stringify(DEBT));
        reportPath = writeTmp('report.txt', [
            'js/moveToDone.js:8: 12.50% duplicated lines > 1%',
            'js/mergeTrigger.js:43: 1.01% duplicated lines > 1%',
            '2/191 files over 1% duplication'
        ].join('\n'));
    }

    test('exits 0 when the report matches the pinned baseline', function() {
        setup();
        assert.strictEqual(ratchet.main([reportPath, baselinePath, '2']), 0);
    });

    test('exits 2 when a fresh file appears over threshold', function() {
        setup();
        reportPath = writeTmp('report-fresh.txt', [
            'js/moveToDone.js:8: 12.50% duplicated lines > 1%',
            'js/mergeTrigger.js:43: 1.01% duplicated lines > 1%',
            'js/brandNewDup.js:3: 4.20% duplicated lines > 1%',
            '3/191 files over 1% duplication'
        ].join('\n'));
        assert.strictEqual(ratchet.main([reportPath, baselinePath, '2']), 2);
    });

    test('exits 2 when a pinned percentage regressed', function() {
        setup();
        reportPath = writeTmp('report-regressed.txt', [
            'js/moveToDone.js:8: 12.50% duplicated lines > 1%',
            'js/mergeTrigger.js:43: 2.00% duplicated lines > 1%',
            '2/191 files over 1% duplication'
        ].join('\n'));
        assert.strictEqual(ratchet.main([reportPath, baselinePath, '2']), 2);
    });

    test('exits 0 on a clean measurement with zero tool violations', function() {
        setup();
        reportPath = writeTmp('report-clean.txt', '191 files, 0.80% duplicated lines');
        assert.strictEqual(ratchet.main([reportPath, baselinePath, '0']), 0);
    });

    test('a crashed measurement (tool exit other than 0/2) never passes', function() {
        setup();
        assert.strictEqual(ratchet.main([reportPath, baselinePath, '1']), 2);
    });

});

// Duplication ratchet for the quality.yml gate (gh-1251 rework).
//
// The `crap4js duplicates --threshold 1` measurement fails with exit 2 while
// ANY production JS file exceeds 1% duplicated lines. 85 files do today —
// pre-existing debt owned by the gh-1244…gh-1250 dedup tickets — so an
// absolute 1% bar can never go green until all seven land. This script turns
// the hard gate into a ratchet: duplication-baseline.json pins every
// currently-over-threshold file with its measured percentage, and the gate
// fails only when the report shows
//
//   - a file over threshold that is NOT pinned (new duplication), or
//   - a pinned file whose percentage GREW (regression).
//
// Shrinking or cleared debt passes (and is reported) — the baseline is
// pruned by the dedup tickets as they land, hardening the gate towards the
// absolute 1% bar it replaces. A measurement that did not run cleanly (tool
// exit other than 0 = no violations, 2 = violations found) never passes.
//
// Usage (see the "Duplication gate" step in .github/workflows/quality.yml):
//   node ci/duplicationRatchet.js <report-file> <baseline-json> <tool-exit-code>
//
// Pure parsing/comparison functions are exported for the unit suite; the
// file-system access lives in main() only, so loadModule() needs no mocks.

'use strict';

var VIOLATION_RE = /^(.+):(\d+): (\d+(?:\.\d+)?)% duplicated lines > /;
var EPSILON = 1e-9;

/**
 * Parse the percentage-mode `crap4js duplicates` report into violation
 * entries. The summary line (`N/M files over T% duplication`) and any other
 * noise are ignored — only `<file>:<line>: NN.NN% duplicated lines > T%`
 * lines match.
 */
function parseViolations(reportText) {
    var violations = [];
    String(reportText || '').split('\n').forEach(function(line) {
        var m = line.match(VIOLATION_RE);
        if (m) {
            violations.push({ file: m[1], line: parseInt(m[2], 10), percent: parseFloat(m[3]) });
        }
    });
    return violations;
}

/**
 * Compare a parsed violation list against the pinned baseline.
 * Returns { clean, fresh, regressions, improved, cleared, pinnedCount }.
 */
function compareWithBaseline(violations, baseline) {
    var pinned = (baseline && baseline.pinned) || {};
    var fresh = [];
    var regressions = [];
    var improved = [];
    var seen = {};
    var pinnedCount = 0;

    violations.forEach(function(v) {
        seen[v.file] = true;
        if (!Object.prototype.hasOwnProperty.call(pinned, v.file)) {
            fresh.push({ file: v.file, percent: v.percent });
        } else if (v.percent > pinned[v.file] + EPSILON) {
            regressions.push({ file: v.file, from: pinned[v.file], to: v.percent });
        } else {
            pinnedCount++;
            if (v.percent < pinned[v.file] - EPSILON) {
                improved.push({ file: v.file, from: pinned[v.file], to: v.percent });
            }
        }
    });

    var cleared = Object.keys(pinned).filter(function(f) { return !seen[f]; });

    return {
        clean: fresh.length === 0 && regressions.length === 0,
        fresh: fresh,
        regressions: regressions,
        improved: improved,
        cleared: cleared,
        pinnedCount: pinnedCount
    };
}

function formatFilePercent(entry) {
    return entry.file + ' ' + entry.percent.toFixed(2) + '%';
}

/**
 * CLI body. Arguments: <report-file> <baseline-json> <tool-exit-code>.
 * Returns the process exit code (0 = ratchet clean, 2 = gate failed).
 */
function main(argv) {
    var fs = require('fs');
    var reportPath = argv[0];
    var baselinePath = argv[1];
    var toolExit = String(argv[2] || '0');

    if (toolExit !== '0' && toolExit !== '2') {
        console.error('duplication ratchet: measurement crashed (tool exit ' + toolExit +
            ') — refusing to pass; report at ' + reportPath);
        return 2;
    }

    var baseline;
    try {
        baseline = JSON.parse(fs.readFileSync(baselinePath, 'utf8'));
    } catch (e) {
        console.error('duplication ratchet: cannot read baseline ' + baselinePath + ': ' + e.message);
        return 2;
    }
    if (!baseline || typeof baseline.pinned !== 'object' || baseline.pinned === null) {
        console.error('duplication ratchet: baseline ' + baselinePath + ' has no "pinned" map');
        return 2;
    }

    var reportText = '';
    try {
        reportText = fs.readFileSync(reportPath, 'utf8');
    } catch (e) {
        console.error('duplication ratchet: cannot read report ' + reportPath + ': ' + e.message);
        return 2;
    }

    var violations = parseViolations(reportText);
    var result = compareWithBaseline(violations, baseline);

    result.improved.forEach(function(i) {
        console.log('improved ' + i.file + ': ' + i.from.toFixed(2) + '% -> ' + i.to.toFixed(2) + '%');
    });
    result.cleared.forEach(function(f) {
        console.log('cleared ' + f + ' — no longer over threshold (baseline entry stale, prune with the dedup PR)');
    });

    if (!result.clean) {
        result.fresh.forEach(function(f) {
            console.error('fresh duplication: ' + formatFilePercent(f) + ' (not pinned in ' + baselinePath + ')');
        });
        result.regressions.forEach(function(r) {
            console.error('duplication regression: ' + r.file + ' ' + r.from.toFixed(2) + '% -> ' + r.to.toFixed(2) + '%');
        });
        console.error('duplication ratchet: FAIL — ' + result.fresh.length + ' fresh, ' +
            result.regressions.length + ' regressed (' + result.pinnedCount + ' pinned debt files unchanged)');
        return 2;
    }

    console.log('duplication ratchet: OK — no new/regressed duplication (' +
        result.pinnedCount + ' pinned debt files, ' + result.cleared.length + ' cleared)');
    return 0;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        parseViolations: parseViolations,
        compareWithBaseline: compareWithBaseline,
        main: main
    };
}

// CLI entry: only when executed directly, not when eval-loaded by the harness.
if (typeof require !== 'undefined' && require.main === module) {
    process.exit(main(process.argv.slice(2)));
}

