- `classifyViolation(v, entry, total)` → {kind: 'fresh'|'regression'|'improved'|'shifted'|'pinned', ...} — pure per-file decision:
```
function classifyViolation(v, entry, total) {
   if (!entry || typeof entry.lines !== 'number') return { kind: 'fresh', file: v.file, percent: v.percent };
   if (typeof total !== 'number') return { kind: 'error', message: 'cannot determine line count of ' + v.file };
   var absNow = recoverDupLines(v.percent, total);
   if (absNow > entry.lines) return { kind: 'regression', file: v.file, fromLines: entry.lines, toLines: absNow };
   if (absNow < entry.lines) return { kind: 'improved', file: v.file, fromLines: entry.lines, toLines: absNow };
   if (v.percent !== entry.pct) return { kind: 'shifted', file: v.file, fromPct: entry.pct, toPct: v.percent, lines: absNow };
   return { kind: 'pinned', file: v.file };
}
